import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

export async function GET(request: NextRequest) {
  const requestUrl = new URL(request.url);
  const code = requestUrl.searchParams.get('code');
  const origin = requestUrl.origin;

  // Check for error parameters
  const error = requestUrl.searchParams.get('error');
  const errorCode = requestUrl.searchParams.get('error_code');
  const errorDescription = requestUrl.searchParams.get('error_description');

  console.log('Auth callback received:', {
    code: code ? 'present' : 'missing',
    error,
    errorCode,
    errorDescription,
    url: request.url
  });

  // If there's an error, redirect to login with the error
  if (error || errorCode) {
    console.error('Auth callback error:', { error, errorCode, errorDescription });
    return NextResponse.redirect(`${origin}/login?error=${errorCode || error}`);
  }

  if (!code) {
    console.error('No code parameter found in auth callback');
    return NextResponse.redirect(`${origin}/login?error=no_code`);
  }

  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

  if (!supabaseUrl || !supabaseKey) {
    console.error('Missing Supabase environment variables');
    return NextResponse.redirect(`${origin}/login?error=config_error`);
  }

  const supabase = createClient(supabaseUrl, supabaseKey);

  try {
    const { data, error: sessionError } = await supabase.auth.exchangeCodeForSession(code);

    if (sessionError) {
      console.error('Error exchanging code for session:', sessionError);
      return NextResponse.redirect(`${origin}/login?error=auth_callback_error`);
    }

    console.log('Successfully exchanged code for session');
    return NextResponse.redirect(`${origin}/play`);
  } catch (error) {
    console.error('Unexpected error in auth callback:', error);
    return NextResponse.redirect(`${origin}/login?error=auth_callback_error`);
  }
}

