import { Progress } from '@/components/ui/progress';
import { getDesignerLevel } from '@/lib/questions';
import { motion } from 'framer-motion';
import { Medal, Trophy } from '@phosphor-icons/react';
import StreakCounter from '@/components/StreakCounter';

interface ScoreDisplayProps {
  score: number;
  currentQuestion: number;
  totalQuestions: number;
  level: number;
  roundScore?: number;
  streak?: number;
}

export function ScoreDisplay({
  score,
  currentQuestion,
  totalQuestions,
  level,
  roundScore = 0,
  streak = 0
}: ScoreDisplayProps) {
  const progress = (currentQuestion / totalQuestions) * 100;
  const designerLevel = getDesignerLevel(score);
  // Get just the first word of the designer level for mobile
  const shortDesignerLevel = designerLevel.split(' ')[0];

  return (
    <div className="w-full max-w-3xl mx-auto mb-8">
      <div className="flex justify-between items-center mb-2">
        <motion.div
          className="text-sm font-medium flex items-center"
          initial={{ opacity: 0, x: -10 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.3 }}
        >
          <span className="inline-flex items-center justify-center w-6 h-6 rounded-full bg-primary/10 text-primary mr-2">
            {currentQuestion}
          </span>
          <span>of {totalQuestions} Questions</span>
        </motion.div>
        <motion.div
          className="text-sm font-medium flex items-center gap-2"
          initial={{ opacity: 0, x: 10 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.3 }}
        >
          {streak > 1 && <StreakCounter streak={streak} />}
          <div className="flex items-center">
            <Trophy weight="fill" className="h-4 w-4 mr-1 text-amber-500" />
            <span>Level {level}</span>
          </div>
        </motion.div>
      </div>

      <motion.div
        initial={{ scaleX: 0 }}
        animate={{ scaleX: 1 }}
        transition={{ duration: 0.5, ease: "easeOut" }}
      >
        <Progress value={progress} className="h-2" />
      </motion.div>

      {/* Desktop Score Display */}
      <div className="hidden md:flex justify-between items-center mt-4">
        <motion.div
          className="text-sm flex items-center"
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3, delay: 0.2 }}
        >
          <span className="font-semibold mr-1">Total Score:</span>
          <motion.div
            key={score}
            initial={{ scale: 1.5, backgroundColor: "rgba(34, 197, 94, 0.3)" }}
            animate={{ scale: 1, backgroundColor: "rgba(34, 197, 94, 0)" }}
            transition={{ duration: 0.5 }}
            className="px-2 py-0.5 rounded-md"
          >
            <span className="text-foreground dark:text-white">{score}</span>
          </motion.div>
        </motion.div>

        <motion.div
          className="text-sm flex items-center"
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3, delay: 0.25 }}
        >
          <span className="font-semibold mr-1">Round Score:</span>
          <motion.div
            key={roundScore}
            initial={{ scale: 1.5, backgroundColor: "rgba(34, 197, 94, 0.3)" }}
            animate={{ scale: 1, backgroundColor: "rgba(34, 197, 94, 0)" }}
            transition={{ duration: 0.5 }}
            className="px-2 py-0.5 rounded-md"
          >
            <span className="text-foreground dark:text-white">{roundScore}</span>
          </motion.div>
        </motion.div>

        <motion.div
          className="text-sm flex items-center"
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3, delay: 0.3 }}
        >
          <Medal weight="fill" className="h-4 w-4 mr-1 text-primary" />
          <span className="font-semibold mr-1">Designer Level:</span>
          <span className="text-foreground dark:text-white">{designerLevel}</span>
        </motion.div>
      </div>

      {/* Mobile Score Display */}
