import { TriviaQuestion } from '@/types';

// Keys for localStorage
const GUEST_SCORE_KEY = 'lighthaus_guest_score';
const GUEST_ANSWERS_KEY = 'lighthaus_guest_answers';
const GUEST_COMPLETED_QUESTIONS_KEY = 'lighthaus_guest_completed_questions';
const SHOWN_BADGES_KEY = 'lighthaus_shown_badges';
const GUEST_SESSION_KEY = 'lighthaus_guest_session';
const GUEST_LAST_ACTIVITY_KEY = 'lighthaus_guest_last_activity';

// Session timeout in milliseconds (30 minutes)
const SESSION_TIMEOUT = 30 * 60 * 1000;

// Types for guest data
export interface GuestAnswer {
    questionId: string;
    selectedOption: string;
    isCorrect: boolean;
    timestamp: string;
    timeTaken: number;
    pointsEarned: number;
}

export interface GuestScore {
    totalScore: number;
    currentLevel: number;
    currentStreak: number;
    highestStreak: number;
    completedQuestions: string[];
    categoryProgress: Record<string, {
        completed: number;
        correct: number;
        total_points: number;
    }>;
    sessionId: string; // Track the current session
    lastActivity: number; // Track the last activity timestamp
}

// Generate a random session ID
function generateSessionId(): string {
    return Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
}

// Initialize guest score
export function initializeGuestScore(): GuestScore {
    const sessionId = generateSessionId();
    const now = Date.now();

    // Save the session ID and last activity timestamp
    if (typeof window !== 'undefined') {
        localStorage.setItem(GUEST_SESSION_KEY, sessionId);
        localStorage.setItem(GUEST_LAST_ACTIVITY_KEY, now.toString());
    }

    return {
        totalScore: 0,
        currentLevel: 1,
        currentStreak: 0,
        highestStreak: 0,
        completedQuestions: [],
        categoryProgress: {},
        sessionId,
        lastActivity: now
    };
}

// Reset guest score
export function resetGuestScore(): void {
    if (typeof window === 'undefined') return;

    // Clear all guest-related data
    localStorage.removeItem(GUEST_SCORE_KEY);
    localStorage.removeItem(GUEST_ANSWERS_KEY);
    localStorage.removeItem(GUEST_COMPLETED_QUESTIONS_KEY);

    // Initialize a new guest score
    const newScore = initializeGuestScore();
    saveGuestScore(newScore);
}

// Check if the guest session is valid
function isGuestSessionValid(): boolean {
    if (typeof window === 'undefined') return false;

    // Get the stored session ID and last activity timestamp
    const storedSessionId = localStorage.getItem(GUEST_SESSION_KEY);
    const storedLastActivity = localStorage.getItem(GUEST_LAST_ACTIVITY_KEY);

    if (!storedSessionId || !storedLastActivity) return false;

    // Check if the session has expired
    const lastActivity = parseInt(storedLastActivity, 10);
    const now = Date.now();

    if (now - lastActivity > SESSION_TIMEOUT) {
        // Session has expired, reset the guest score
        resetGuestScore();
        return false;
    }

    // Update the last activity timestamp
    localStorage.setItem(GUEST_LAST_ACTIVITY_KEY, now.toString());

    return true;
}

// Get guest score from localStorage
export function getGuestScore(): GuestScore {
    if (typeof window === 'undefined') return initializeGuestScore();

    // Check if the guest session is valid
    if (!isGuestSessionValid()) {
        return initializeGuestScore();
    }

    const storedScore = localStorage.getItem(GUEST_SCORE_KEY);
    if (!storedScore) return initializeGuestScore();

    try {
        const score = JSON.parse(storedScore) as GuestScore;

        // Update the last activity timestamp
        score.lastActivity = Date.now();
        saveGuestScore(score);

        return score;
    } catch (error) {
        console.error('Error parsing guest score from localStorage:', error);
        return initializeGuestScore();
    }
}

// Save guest score to localStorage
export function saveGuestScore(score: GuestScore): void {
    if (typeof window === 'undefined') return;

    // Update the last activity timestamp
    score.lastActivity = Date.now();
    localStorage.setItem(GUEST_LAST_ACTIVITY_KEY, score.lastActivity.toString());

    localStorage.setItem(GUEST_SCORE_KEY, JSON.stringify(score));
}

// Get guest answers from localStorage
export function getGuestAnswers(): GuestAnswer[] {
    if (typeof window === 'undefined') return [];

    const storedAnswers = localStorage.getItem(GUEST_ANSWERS_KEY);
    if (!storedAnswers) return [];

    try {
        return JSON.parse(storedAnswers) as GuestAnswer[];
    } catch (error) {
        console.error('Error parsing guest answers from localStorage:', error);
        return [];
    }
}

// Save a guest answer to localStorage
export function saveGuestAnswer(answer: GuestAnswer): void {
    if (typeof window === 'undefined') return;

    const answers = getGuestAnswers();
    answers.push(answer);
    localStorage.setItem(GUEST_ANSWERS_KEY, JSON.stringify(answers));
}

// Update guest score based on an answer
export function updateGuestScoreWithAnswer(
    question: TriviaQuestion,
    isCorrect: boolean,
    pointsEarned: number,
    timeBonus: number
): GuestScore {
    const score = getGuestScore();

    // Add question to completed questions
    if (!score.completedQuestions.includes(question.id.toString())) {
        score.completedQuestions.push(question.id.toString());
    }

    if (isCorrect) {
        // Update total score
        score.totalScore += pointsEarned;

        // Update streak
        score.currentStreak += 1;
        if (score.currentStreak > score.highestStreak) {
            score.highestStreak = score.currentStreak;
        }

        // Update category progress
        const category = question.category;
        if (!score.categoryProgress[category]) {
            score.categoryProgress[category] = {
                completed: 0,
                correct: 0,
                total_points: 0
            };
        }

        score.categoryProgress[category].completed += 1;
        score.categoryProgress[category].correct += 1;
        score.categoryProgress[category].total_points += pointsEarned;
    } else {
        // Reset streak on wrong answer
        score.currentStreak = 0;

        // Update category progress (only completed)
        const category = question.category;
        if (!score.categoryProgress[category]) {
            score.categoryProgress[category] = {
                completed: 0,
                correct: 0,
                total_points: 0
            };
        }

        score.categoryProgress[category].completed += 1;
    }

    // Save updated score
    saveGuestScore(score);

    return score;
}

// Clear guest data (e.g., after migration to user account)
export function clearGuestData(): void {
    if (typeof window === 'undefined') return;
    localStorage.removeItem(GUEST_SCORE_KEY);
    localStorage.removeItem(GUEST_ANSWERS_KEY);
    localStorage.removeItem(GUEST_COMPLETED_QUESTIONS_KEY);
}

// Check if guest has played before
export function hasGuestPlayed(): boolean {
    if (typeof window === 'undefined') return false;

    const score = getGuestScore();
    return score.completedQuestions.length > 0;
}

// Functions for managing shown badges

/**
 * Gets the list of badge IDs that have already been shown to the user
 */
export function getShownBadges(): string[] {
    try {
        const shownBadges = localStorage.getItem(SHOWN_BADGES_KEY);
        return shownBadges ? JSON.parse(shownBadges) : [];
    } catch (error) {
        console.error('Error getting shown badges:', error);
        return [];
    }
}

/**
 * Adds badge IDs to the list of shown badges
 */
export function addShownBadges(badgeIds: string[]): void {
    try {
        const currentShownBadges = getShownBadges();
        // Create a combined array and convert to a Set to remove duplicates, then back to array
        const combinedArray = [...currentShownBadges, ...badgeIds];
        const uniqueSet = new Set(combinedArray);
        const updatedShownBadges = Array.from(uniqueSet);
        localStorage.setItem(SHOWN_BADGES_KEY, JSON.stringify(updatedShownBadges));
    } catch (error) {
        console.error('Error saving shown badges:', error);
    }
}

/**
 * Clears the list of shown badges
 */
export function clearShownBadges(): void {
    localStorage.removeItem(SHOWN_BADGES_KEY);
}

